CREATE TABLE gov_policies(organization_id uuid NOT NULL REFERENCES organizations(id), id uuid NOT NULL, circle_id uuid NOT NULL, version int NOT NULL DEFAULT 1, configuration jsonb NOT NULL, PRIMARY KEY(organization_id,id), UNIQUE(organization_id,circle_id), FOREIGN KEY(organization_id,circle_id) REFERENCES entities(organization_id,id));
CREATE TABLE gov_tensions(organization_id uuid NOT NULL REFERENCES organizations(id),id uuid NOT NULL, author_id uuid NOT NULL,circle_id uuid NOT NULL,title text NOT NULL,description text NOT NULL DEFAULT '',state text NOT NULL DEFAULT 'OPEN' CHECK(state IN ('OPEN','PROCESSED','CLOSED')),version int NOT NULL DEFAULT 1,PRIMARY KEY(organization_id,id),FOREIGN KEY(organization_id,author_id) REFERENCES members(organization_id,id),FOREIGN KEY(organization_id,circle_id) REFERENCES entities(organization_id,id));
CREATE TABLE gov_branches(organization_id uuid NOT NULL REFERENCES organizations(id),id uuid NOT NULL,author_id uuid NOT NULL,title text NOT NULL,changes jsonb NOT NULL,base_structure_revision int NOT NULL,state text NOT NULL DEFAULT 'OPEN' CHECK(state IN ('OPEN','APPLIED','CLOSED')),version int NOT NULL DEFAULT 1,PRIMARY KEY(organization_id,id),FOREIGN KEY(organization_id,author_id) REFERENCES members(organization_id,id));
CREATE TABLE gov_documents(organization_id uuid NOT NULL REFERENCES organizations(id),id uuid NOT NULL,owner_id uuid NOT NULL,title text NOT NULL,workflow text NOT NULL CHECK(workflow IN ('DIRECT','GOVERNANCE')),visibility text NOT NULL CHECK(visibility IN ('ORGANIZATION','AUTHOR')),author_id uuid NOT NULL,version int NOT NULL DEFAULT 1,published_version int,archived boolean NOT NULL DEFAULT false,PRIMARY KEY(organization_id,id),FOREIGN KEY(organization_id,owner_id) REFERENCES entities(organization_id,id),FOREIGN KEY(organization_id,author_id) REFERENCES members(organization_id,id));
CREATE TABLE gov_document_versions(organization_id uuid NOT NULL,document_id uuid NOT NULL,number int NOT NULL,content text NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(organization_id,document_id,number),FOREIGN KEY(organization_id,document_id) REFERENCES gov_documents(organization_id,id),FOREIGN KEY(organization_id,created_by) REFERENCES members(organization_id,id));
ALTER TABLE gov_documents ADD FOREIGN KEY(organization_id,id,published_version) REFERENCES gov_document_versions(organization_id,document_id,number) DEFERRABLE INITIALLY DEFERRED;
CREATE TABLE gov_proposals(organization_id uuid NOT NULL REFERENCES organizations(id),id uuid NOT NULL,circle_id uuid NOT NULL,author_id uuid NOT NULL,tension_id uuid,branch_id uuid,title text NOT NULL,kind text NOT NULL CHECK(kind IN ('GOVERNANCE','DOCUMENT','ELECTION')),revision int NOT NULL DEFAULT 1,version int NOT NULL DEFAULT 1,state text NOT NULL DEFAULT 'DRAFT' CHECK(state IN ('DRAFT','REVIEW','DECIDED','WITHDRAWN')),verdict text,apply_state text NOT NULL DEFAULT 'PENDING' CHECK(apply_state IN ('PENDING','APPLIED','APPLY_CONFLICT')),first_submitted_at timestamptz,PRIMARY KEY(organization_id,id),FOREIGN KEY(organization_id,circle_id) REFERENCES entities(organization_id,id),FOREIGN KEY(organization_id,author_id) REFERENCES members(organization_id,id),FOREIGN KEY(organization_id,tension_id) REFERENCES gov_tensions(organization_id,id),FOREIGN KEY(organization_id,branch_id) REFERENCES gov_branches(organization_id,id));
CREATE TABLE gov_revisions(organization_id uuid NOT NULL,proposal_id uuid NOT NULL,number int NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(organization_id,proposal_id,number),FOREIGN KEY(organization_id,proposal_id) REFERENCES gov_proposals(organization_id,id));
CREATE TABLE gov_rounds(organization_id uuid NOT NULL,id uuid NOT NULL,proposal_id uuid NOT NULL,revision int NOT NULL,policy jsonb NOT NULL,electorate uuid[] NOT NULL,deadline timestamptz,state text NOT NULL DEFAULT 'OPEN' CHECK(state IN ('OPEN','CLOSED','SUPERSEDED')),step text NOT NULL DEFAULT 'PRESENT',decision_reason text,PRIMARY KEY(organization_id,id),UNIQUE(organization_id,proposal_id,revision),FOREIGN KEY(organization_id,proposal_id,revision) REFERENCES gov_revisions(organization_id,proposal_id,number),CHECK(cardinality(electorate)>0));
CREATE TABLE gov_ballots(organization_id uuid NOT NULL,round_id uuid NOT NULL,member_id uuid NOT NULL,number int NOT NULL,choice text NOT NULL CHECK(choice IN ('CONSENT','ABSTAIN','OBJECT')),rationale text NOT NULL,at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(organization_id,round_id,member_id,number),FOREIGN KEY(organization_id,round_id) REFERENCES gov_rounds(organization_id,id),FOREIGN KEY(organization_id,member_id) REFERENCES members(organization_id,id));
CREATE TABLE gov_objections(organization_id uuid NOT NULL,id uuid NOT NULL,round_id uuid NOT NULL,author_id uuid NOT NULL,rationale text NOT NULL,state text NOT NULL DEFAULT 'RAISED' CHECK(state IN ('RAISED','TESTING','VALID','INTEGRATED','INVALID','WITHDRAWN')),resolution text,version int NOT NULL DEFAULT 1,PRIMARY KEY(organization_id,id),FOREIGN KEY(organization_id,round_id) REFERENCES gov_rounds(organization_id,id),FOREIGN KEY(organization_id,author_id) REFERENCES members(organization_id,id));
CREATE TABLE gov_nominations(organization_id uuid NOT NULL,id uuid NOT NULL,proposal_id uuid NOT NULL,candidate_id uuid NOT NULL,author_id uuid NOT NULL,rationale text NOT NULL,PRIMARY KEY(organization_id,id),UNIQUE(organization_id,proposal_id,candidate_id,author_id),FOREIGN KEY(organization_id,proposal_id) REFERENCES gov_proposals(organization_id,id),FOREIGN KEY(organization_id,candidate_id) REFERENCES members(organization_id,id),FOREIGN KEY(organization_id,author_id) REFERENCES members(organization_id,id));
CREATE TABLE gov_commits(organization_id uuid NOT NULL,id uuid NOT NULL,proposal_id uuid,revision int,branch_id uuid,changes jsonb NOT NULL,at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(organization_id,id),UNIQUE(organization_id,proposal_id,revision),UNIQUE(organization_id,branch_id),FOREIGN KEY(organization_id,proposal_id,revision) REFERENCES gov_revisions(organization_id,proposal_id,number),FOREIGN KEY(organization_id,branch_id) REFERENCES gov_branches(organization_id,id));
CREATE TABLE gov_history(organization_id uuid NOT NULL,id uuid NOT NULL,resource_id uuid NOT NULL,actor_id uuid NOT NULL,action text NOT NULL,snapshot jsonb NOT NULL,at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(organization_id,id),FOREIGN KEY(organization_id,actor_id) REFERENCES members(organization_id,id));
ALTER TABLE gov_policies ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant ON gov_policies USING(organization_id=nullif(current_setting('orgmap.organization_id',true),'')::uuid) WITH CHECK(organization_id=nullif(current_setting('orgmap.organization_id',true),'')::uuid);
